const birthdateInput=document.getElementById("birthdate"),calculateBtn=document.getElementById("calculate-btn"),ageResult=document.getElementById("age-result"),nextBirthday=document.getElementById("next-birthday"),ageMain=document.getElementById("age-main"),yearsSpan=document.getElementById("years"),monthsSpan=document.getElementById("months"),daysSpan=document.getElementById("days"),hoursSpan=document.getElementById("hours"),minutesSpan=document.getElementById("minutes"),secondsSpan=document.getElementById("seconds"),nextBirthdayText=document.getElementById("next-birthday-text"),today=(new Date).toISOString().split("T")[0];function calculateAge(){const t=new Date(birthdateInput.value),e=new Date;if(!birthdateInput.value)return void alert("Please select your birth date.");if(t>e)return void alert("Birth date cannot be in the future.");let n=e.getFullYear()-t.getFullYear(),a=e.getMonth()-t.getMonth(),o=e.getDate()-t.getDate();o<0&&(a--,o+=new Date(e.getFullYear(),e.getMonth(),0).getDate()),a<0&&(n--,a+=12);const d=12*n+a,l=Math.floor((e-t)/864e5),r=24*l,c=60*r,i=60*c,u=e.getFullYear();let s=new Date(u,t.getMonth(),t.getDate());s<e&&(s=new Date(u+1,t.getMonth(),t.getDate()));const g=Math.ceil((s-e)/864e5);ageMain.textContent=`You are ${n} years old!`,yearsSpan.textContent=n,monthsSpan.textContent=d.toLocaleString(),daysSpan.textContent=l.toLocaleString(),hoursSpan.textContent=r.toLocaleString(),minutesSpan.textContent=c.toLocaleString(),secondsSpan.textContent=i.toLocaleString(),nextBirthdayText.textContent=`${g} days from now (${s.toLocaleDateString()})`,ageResult.classList.remove("hidden"),nextBirthday.classList.remove("hidden")}birthdateInput.max=today,calculateBtn.addEventListener("click",calculateAge),birthdateInput.addEventListener("keypress",t=>{"Enter"===t.key&&calculateAge()}),document.getElementById("back-to-tools-btn").addEventListener("click",function(t){t.preventDefault(),window.location.href="/#utility-tools-section"});